import{c as a,Q as d,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const e="/assets/%E5%B8%B8%E9%87%8F%E5%A1%AB%E5%85%85%E6%A8%A1%E5%BC%8F%EF%BC%88%E5%9B%BE%E7%89%87%E4%B8%AD%E9%97%B4%E7%9A%84%E7%BB%BF%E8%89%B2%E5%8C%BA%E5%9F%9F%E8%A1%A8%E7%A4%BA%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE-%E5%85%B6%E4%BB%96%E4%B8%BApadding%E6%95%B0%E6%8D%AE%EF%BC%89.Dul9JksK.png",i="/assets/%E8%A1%8C%E5%88%97%E5%A1%AB%E5%85%85%E6%A8%A1%E5%BC%8F%EF%BC%88%E5%9B%BE%E7%89%87%E4%B8%AD%E9%97%B4%E7%9A%84%E7%BB%BF%E8%89%B2%E5%8C%BA%E5%9F%9F%E8%A1%A8%E7%A4%BA%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE-%E5%85%B6%E4%BB%96%E4%B8%BApadding%E6%95%B0%E6%8D%AE%EF%BC%89.B6UwRBhe.png",p="/assets/%E5%9D%97%E5%A1%AB%E5%85%85%E6%A8%A1%E5%BC%8F%EF%BC%88%E5%9B%BE%E7%89%87%E4%B8%AD%E9%97%B4%E7%9A%84%E7%BB%BF%E8%89%B2%E5%8C%BA%E5%9F%9F%E8%A1%A8%E7%A4%BA%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE-%E5%85%B6%E4%BB%96%E4%B8%BApadding%E6%95%B0%E6%8D%AE%EF%BC%89.D6CwDZQD.png",r="/assets/%E9%95%9C%E5%83%8F%E5%9D%97%E5%A1%AB%E5%85%85%E6%A8%A1%E5%BC%8F%EF%BC%88%E5%9B%BE%E7%89%87%E4%B8%AD%E9%97%B4%E7%9A%84%E7%BB%BF%E8%89%B2%E5%8C%BA%E5%9F%9F%E8%A1%A8%E7%A4%BA%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE-%E5%85%B6%E4%BB%96%E4%B8%BApadding%E6%95%B0%E6%8D%AE%EF%BC%89.CFV5RJFD.png",l="/assets/zh-cn_formulaimage_0000001938335310.CiABFIKx.png",o="/assets/zh-cn_formulaimage_0000001938176178.CPU0pjGq.png",C=JSON.parse('{"title":"SetAippFunctions","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetAippFunctions","slug":"setaippfunctions"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetAippFunctions.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetAippFunctions.md"}'),c={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetAippFunctions.md"};function u(h,t,g,A,B,m){return d(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="setaippfunctions" tabindex="-1">SetAippFunctions <a class="header-anchor" href="#setaippfunctions" aria-label="Permalink to &quot;SetAippFunctions&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置图片预处理（AIPP，AI core pre-process）相关参数。和<a href="./LoadImageToLocal.html">LoadImageToLocal</a>接口配合使用。设置后，调用<a href="./LoadImageToLocal.html">LoadImageToLocal</a>接口可在搬运过程中完成图像预处理操作：包括数据填充，通道交换，单行读取、数据类型转换、通道填充、色域转换。调用SetAippFunctions接口时需传入源图片在Global Memory上的矩阵、源图片的图片格式。</p><ul><li><p><strong>数据填充</strong>：在图片HW方向上padding。分为如下几种模式：</p><ul><li><p>模式0：常量填充模式，padding区域各位置填充为常数，支持设置每个通道填充的常数。该模式下仅支持左右padding，不支持上下padding。</p><p><strong>图 1</strong> 常量填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<br><img src="'+e+'" alt="" title="常量填充模式（图片中间的绿色区域表示原始数据-其他为padding数据）"></p></li><li><p>模式1：行列填充模式，padding区域各位置填充行/列上最邻近源图片位置的数据。</p><p><strong>图 2</strong> 行列填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<br><img src="'+i+'" alt="" title="行列填充模式（图片中间的绿色区域表示原始数据-其他为padding数据）"></p></li><li><p>模式2：块填充模式，按照padding的宽高，从源图片拷贝数据块进行padding区域填充。</p><p><strong>图 3</strong> 块填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<br><img src="'+p+'" alt="" title="块填充模式（图片中间的绿色区域表示原始数据-其他为padding数据）"></p></li><li><p>模式3：镜像块填充模式，按照padding的宽高，从源图片拷贝数据块的镜像进行padding区域填充。</p><p><strong>图 4</strong> 镜像块填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<br><img src="'+r+`" alt="" title="镜像块填充模式（图片中间的绿色区域表示原始数据-其他为padding数据）"></p></li></ul></li><li><p><strong>通道交换</strong>：将图片通道进行交换。</p><p>对于RGB888格式，支持交换R和B通道。</p><p>对于YUV420SP格式，支持交换U和V通道。</p><p>对于XRGB8888格式，支持X通道后移（XRGB-&gt;RGBX）、支持交换R和B通道。</p></li><li><p><strong>单行读取</strong>：源图片中仅读取一行。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>调用数据搬运接口时，开启单行读取后设置的目的图片高度参数无效，如<a href="./LoadImageToLocal.html">LoadImageToLocal</a>接口的loadImageToLocalParams.vertSize。</p></div></li><li><p><strong>数据类型转换</strong>：转换像素的数据类型，支持uint8_t转换为int8_t或half。当uint8_t转换成int8_t的时候，输出数据范围限制在[-128， 127]。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 例1：实现uint8_t -&gt;int8_t 的类型转换，同时实现零均值化：设置每个通道mean值为该通道所有数据的平均值（min和var值无效，不用设置）。</span></span>
<span class="line"><span>output[i][j][k] = input[i][j][k] - mean[k]</span></span>
<span class="line"><span>// 例2：实现uint8_t -&gt; fp16 的类型转换，同时实现归一化：设置每个通道mean值为该通道所有数据的平均值，min值为该通道所有数据零均值化后的最小值，var值为该通道所有数据的最大值减最小值的倒数。</span></span>
<span class="line"><span>uint8_t -&gt; fp16:  output[i][j][k] = (input[i][j][k] - mean[k] - min[k]) * var[k]</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>转换后的数据类型是由模板参数U配置，U为uint8_t时数据类型转换功能不生效。 调用数据搬运接口时，目的Tensor的数据类型需要与本接口输出数据类型保持一致，如<a href="./LoadImageToLocal.html">LoadImageToLocal</a>的dstLocal参数的数据类型。</p></div></li><li><p><strong>通道填充</strong>：在图片通道方向上padding。默认为模式0。</p><p>模式0：将通道padding至32Bytes。即输出数据类型为uint8_t/int8_t时，padding至32通道；输出数据类型为fp16时，padding至16通道。</p><p>模式1：将通道padding至4通道。</p></li><li><p><strong>色域转换</strong>：RGB格式转换为YUV格式，或YUV模式转换为RGB格式。</p><p><img src="`+l+'" alt=""></p><p><img src="'+o+`" alt=""></p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>输入图片格式为YUV400、RGB888、XRGB8888</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void SetAippFunctions(const GlobalTensor&lt;T&gt;&amp; src0, AippInputFormat format, AippParams&lt;U&gt; config)</span></span></code></pre></div></li><li><p>输入图片格式为YUV420 Semi-Planar</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void SetAippFunctions(const GlobalTensor&lt;T&gt;&amp; src0, const GlobalTensor&lt;T&gt;&amp; src1, AippInputFormat format, AippParams&lt;U&gt; config)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>输入的数据类型，需要与format中设置的数据类型保持一致。</td></tr><tr><td>U</td><td>输出的数据类型，需要在搬运接口配置同样的数据类型，如LoadImageToLocal的dstLocal参数数据类型。 如果不使能数据类型转换功能，需要与输入类型保持一致；如果使能数据类型转换功能，需要与期望转换后的类型保持一致。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>src0</td><td>输入</td><td>源图片在Global Memory上的矩阵。 源图片格式为YUV420SP时，表示Y维度在Global Memory上的矩阵。</td></tr><tr><td>src1</td><td>输入</td><td>源图片格式为YUV420SP时，表示UV维度在Global Memory上的矩阵。 源图片格式为其他格式时，该参数无效。</td></tr><tr><td>format</td><td>输入</td><td>源图片的图片格式。AippInputFormat为枚举类型，取值为： AippInputFormat::YUV420SP_U8：图片格式为YUV420 Semi-Planar，数据类型为uint8_t AippInputFormat::XRGB8888_U8：图片格式为XRGB8888，数据类型为uint8_t AippInputFormat::RGB888_U8：图片格式为RGB888，数据类型为uint8_t AippInputFormat::YUV400_U8：图片格式为YUV400，数据类型为uint8_t &lt;pre class=&quot;screen&quot; id=&quot;screen197391367335&quot;&gt;enum class AippInputFormat : uint8_t { YUV420SP_U8 = 0, XRGB8888_U8 = 1, RGB888_U8 = 4, YUV400_U8 = 9, };&lt;/pre&gt;</td></tr><tr><td>config</td><td>输入</td><td>图片预处理的相关参数，类型为AippParams，结构体具体定义为： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen14291456104811&quot;&gt;template &lt;typename T&gt; struct AippParams { AippPaddingParams&lt;T&gt; paddingParams; AippSwapParams swapParams; AippSingleLineParams singleLineParams; AippDataTypeConvParams dtcParams; AippChannelPaddingParams&lt;T&gt; cPaddingParams; AippColorSpaceConvParams cscParams; };&lt;/pre&gt; AippParams结构体内各子结构体定义如下： 数据填充功能相关参数，说明见表3。&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen117911942165117&quot;&gt;template &lt;typename T&gt; struct AippPaddingParams { uint32_t paddingMode; T paddingValueCh0; T paddingValueCh1; T paddingValueCh2; T paddingValueCh3; };&lt;/pre&gt; 通道交换功能相关参数，说明见表4。&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen10865103665215&quot;&gt;struct AippSwapParams { bool isSwapRB; bool isSwapUV; bool isSwapAX; };&lt;/pre&gt; 单行读取功能相关参数，说明见表5。&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1187335714526&quot;&gt;struct AippSingleLineParams { bool isSingleLineCopy; };&lt;/pre&gt; 数据类型转换功能相关参数，说明见表6。&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen11371618165312&quot;&gt;struct AippDataTypeConvParams { uint8_t dtcMeanCh0{ 0 }; uint8_t dtcMeanCh1{ 0 }; uint8_t dtcMeanCh2{ 0 }; half dtcMinCh0{ 0 }; half dtcMinCh1{ 0 }; half dtcMinCh2{ 0 }; half dtcVarCh0{ 1.0 }; half dtcVarCh1{ 1.0 }; half dtcVarCh2{ 1.0 }; uint32_t dtcRoundMode{ 0 }; };&lt;/pre&gt; 通道填充功能相关参数，说明见表7。&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1319711065418&quot;&gt;template &lt;typename T&gt; struct AippChannelPaddingParams { uint32_t cPaddingMode; T cPaddingValue; };&lt;/pre&gt; 色域转换功能相关参数，说明见表8。&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen873561816545&quot;&gt;struct AippColorSpaceConvParams { bool isEnableCsc; int16_t cscMatrixR0C0; int16_t cscMatrixR0C1; int16_t cscMatrixR0C2; int16_t cscMatrixR1C0; int16_t cscMatrixR1C1; int16_t cscMatrixR1C2; int16_t cscMatrixR2C0; int16_t cscMatrixR2C1; int16_t cscMatrixR2C2; uint8_t cscBiasIn0; uint8_t cscBiasIn1; uint8_t cscBiasIn2; uint8_t cscBiasOut0; uint8_t cscBiasOut1; uint8_t cscBiasOut2; };&lt;/pre&gt;</td></tr></tbody></table><p><strong>表 3</strong> AippPaddingParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>paddingMode</td><td>输入</td><td>padding的模式，取值范围[0, 3]，默认值为0。 0：常数填充模式，此模式仅支持左右填充。 1：行列拷贝模式。 2：块拷贝模式。 3：镜像块拷贝模式。</td></tr><tr><td>paddingValueCh0</td><td>输入</td><td>padding区域中channel0填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr><tr><td>paddingValueCh1</td><td>输入</td><td>padding区域中channel1填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr><tr><td>paddingValueCh2</td><td>输入</td><td>padding区域中channel2填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr><tr><td>paddingValueCh3</td><td>输入</td><td>padding区域中channel3填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr></tbody></table><p><strong>表 4</strong> AippSwapParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>isSwapRB</td><td>输入</td><td>对于RGB888、XRGB8888格式，是否交换R和B通道。默认值为false。</td></tr><tr><td>isSwapUV</td><td>输入</td><td>对于YUV420SP格式，是否交换U和V通道。默认值为false。</td></tr><tr><td>isSwapAX</td><td>输入</td><td>对于XRGB8888格式，是否将X通道后移，即XRGB-&gt;RGBX。默认值为false。</td></tr></tbody></table><p><strong>表 5</strong> AippSingleLineParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>isSingleLineCopy</td><td>输入</td><td>是否开启单行读取模式。开启后，仅从源图片读取一行。默认值为false。</td></tr></tbody></table><p><strong>表 6</strong> AippDataTypeConvParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dtcMeanCh0</td><td>输入</td><td>计算公式内的mean值，channel0，数据类型为uint8_t，默认值为0。</td></tr><tr><td>dtcMeanCh1</td><td>输入</td><td>计算公式内的mean值，channel1，数据类型为uint8_t，默认值为0。</td></tr><tr><td>dtcMeanCh2</td><td>输入</td><td>计算公式内的mean值，channel2，数据类型为uint8_t，默认值为0。</td></tr><tr><td>dtcMinCh0</td><td>输入</td><td>计算公式内的min值，channel0，数据类型为half，默认值为0。 Atlas 200I/500 A2 推理产品不支持配置该参数。</td></tr><tr><td>dtcMinCh1</td><td>输入</td><td>计算公式内的min值，channel1，数据类型为half，默认值为0。 Atlas 200I/500 A2 推理产品不支持配置该参数。</td></tr><tr><td>dtcMinCh2</td><td>输入</td><td>计算公式内的min值，channel2，数据类型为half，默认值为0。 Atlas 200I/500 A2 推理产品不支持配置该参数。</td></tr><tr><td>dtcVarCh0</td><td>输入</td><td>计算公式内的var值，channel0，数据类型为half，默认值为1.0。</td></tr><tr><td>dtcVarCh1</td><td>输入</td><td>计算公式内的var值，channel1，数据类型为half，默认值为1.0。</td></tr><tr><td>dtcVarCh2</td><td>输入</td><td>计算公式内的var值，channel2，数据类型为half，默认值为1.0。</td></tr><tr><td>dtcRoundMode</td><td>输入</td><td>控制dtc做数据类型转换的模式，数据类型为uint32_t，默认值为0。 0：四舍五入到最接近的整数值（C语言round）。 1：四舍五入到最接近的偶数（C语言rint）。 仅Atlas 200I/500 A2 推理产品支持配置该参数。</td></tr></tbody></table><p><strong>表 7</strong> AippChannelPaddingParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>cPaddingMode</td><td>输入</td><td>channel padding的类型，取值范围为[0, 1]，默认值为0。 0：填充到32B。即输出数据类型U为uint8_t/int8_t时填充到32通道，为half时填充到16通道。 1：填充到4通道。</td></tr><tr><td>cPaddingValue</td><td>输入</td><td>channel padding填充的值，数据类型为T，默认值为0。</td></tr></tbody></table><p><strong>表 8</strong> AippColorSpaceConvParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>isEnableCsc</td><td>输入</td><td>是否开启色域转换功能，默认值为false。</td></tr><tr><td>cscMatrixR0C0</td><td>输入</td><td>色域转换矩阵cscMatrix[0][0]。</td></tr><tr><td>cscMatrixR0C1</td><td>输入</td><td>色域转换矩阵cscMatrix[0][1]。</td></tr><tr><td>cscMatrixR0C2</td><td>输入</td><td>色域转换矩阵cscMatrix[0][2]。</td></tr><tr><td>cscMatrixR1C0</td><td>输入</td><td>色域转换矩阵cscMatrix[1][0]。</td></tr><tr><td>cscMatrixR1C1</td><td>输入</td><td>色域转换矩阵cscMatrix[1][1]。</td></tr><tr><td>cscMatrixR1C2</td><td>输入</td><td>色域转换矩阵cscMatrix[1][2]。</td></tr><tr><td>cscMatrixR2C0</td><td>输入</td><td>色域转换矩阵cscMatrix[2][0]。</td></tr><tr><td>cscMatrixR2C1</td><td>输入</td><td>色域转换矩阵cscMatrix[2][1]。</td></tr><tr><td>cscMatrixR2C2</td><td>输入</td><td>色域转换矩阵cscMatrix[2][2]。</td></tr><tr><td>cscBiasIn0</td><td>输入</td><td>RGB转YUV偏置cscBiasIn[0]。YUV转RGB时无效。</td></tr><tr><td>cscBiasIn1</td><td>输入</td><td>RGB转YUV偏置cscBiasIn[1]。YUV转RGB时无效。</td></tr><tr><td>cscBiasIn2</td><td>输入</td><td>RGB转YUV偏置cscBiasIn[2]。YUV转RGB时无效。</td></tr><tr><td>cscBiasOut0</td><td>输入</td><td>YUV转RGB偏置cscBiasOut0[0]。RGB转YUV时无效。</td></tr><tr><td>cscBiasOut1</td><td>输入</td><td>YUV转RGB偏置cscBiasOut1[1]。RGB转YUV时无效。</td></tr><tr><td>cscBiasOut2</td><td>输入</td><td>YUV转RGB偏置cscBiasOut2[2]。RGB转YUV时无效。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>src0、src1在Global Memory上的地址对齐要求如下：</li></ul><table tabindex="0"><thead><tr><th>图片格式</th><th>src0</th><th>src1</th></tr></thead><tbody><tr><td>YUV420SP</td><td>必须2Bytes对齐</td><td>必须2Bytes对齐</td></tr><tr><td>XRGB8888</td><td>必须4Bytes对齐</td><td>-</td></tr><tr><td>RGB888</td><td>无对齐要求</td><td>-</td></tr><tr><td>YUV400</td><td>无对齐要求</td><td>-</td></tr></tbody></table><ul><li>对于XRGB输入格式的数据，芯片在处理的时候会默认丢弃掉第四个通道的数据输出RGB格式的数据，所以如果是X在channel0的场景下，为了达成上述目的，X通道后移的功能必须使能，将输入的通道转换为RGBX；反之如果是X在channel3的场景下，X通道后移的功能必须不使能以输出RGB格式的数据。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>该调用示例支持的运行平台为Atlas 推理系列产品AI Core，示例图片格式为YUV420SP。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint16_t horizSize = 32, vertSize = 32, horizStartPos = 0, vertStartPos = 0, srcHorizSize = 32, srcVertSize = 32, leftPadSize = 0, rightPadSize = 0;</span></span>
<span class="line"><span>uint32_t dstHorizSize = 32, dstVertSize = 32, cSize = 32;</span></span>
<span class="line"><span>uint8_t topPadSize = 0, botPadSize = 0;</span></span>
<span class="line"><span>uint32_t gmSrc0Size = 0, gmSrc1Size = 0, dstSize = 0;</span></span>
<span class="line"><span>AscendC::AippInputFormat inputFormat = AscendC::AippInputFormat::YUV420SP_U8;</span></span>
<span class="line"><span>uint32_t cPadMode = 0;</span></span>
<span class="line"><span>int8_t cPaddingValue = 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::A1, 1&gt; inQueueA1;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECOUT, 1&gt; outQueueUB;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;int8_t&gt; featureMapA1 = inQueueA1.AllocTensor&lt;int8_t&gt;();</span></span>
<span class="line"><span>uint64_t fm_addr = static_cast&lt;uint64_t&gt;(reinterpret_cast&lt;uintptr_t&gt;(fmGlobal.GetPhyAddr()));</span></span>
<span class="line"><span>        // aipp config</span></span>
<span class="line"><span>AscendC::AippParams&lt;int8_t&gt; aippConfig;</span></span>
<span class="line"><span>aippConfig.cPaddingParams.cPaddingMode = cPadMode;</span></span>
<span class="line"><span>aippConfig.cPaddingParams.cPaddingValue = cPaddingValue;</span></span>
<span class="line"><span>// fmGlobal为整张输入图片，src1参数处填入图片UV维度的起始地址</span></span>
<span class="line"><span>AscendC::SetAippFunctions(fmGlobal, fmGlobal[gmSrc0Size], inputFormat, aippConfig);</span></span>
<span class="line"><span>AscendC::LoadImageToLocal(featureMapA1, { horizSize, vertSize, horizStartPos, vertStartPos, srcHorizSize, topPadSize, botPadSize, leftPadSize, rightPadSize });</span></span></code></pre></div></li></ul>`,33)])])}const b=a(c,[["render",u]]);export{C as __pageData,b as default};
